"use client";

import { useState, useEffect } from "react";
import Link from "next/link";

const LOGO_URL =
  "https://pub-f170a2592d2c4a1485466404c36807be.r2.dev/Tests/logoipsum-415.svg";

function ChevronArrow() {
  return (
    <svg width="12" height="12" viewBox="0 0 24 24" fill="none">
      <path
        d="M5 12h14M13 6l6 6-6 6"
        stroke="currentColor"
        strokeWidth="2.2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function Logo() {
  return (
    <Link href="#" className="flex items-center gap-[9px]" aria-label="nexto home">
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={LOGO_URL} alt="" className="h-7 brightness-0" />
      <span className="text-[20px] font-bold tracking-[-0.3px] text-[#111]">nexto.</span>
    </Link>
  );
}

export default function Navbar() {
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    document.body.style.overflow = menuOpen ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [menuOpen]);

  return (
    <>
      <nav className="sticky top-0 z-50 backdrop-saturate-[180%] backdrop-blur-[10px] bg-[rgba(245,245,245,0.7)]">
        <div className="max-w-[1100px] mx-auto px-10 py-6 flex items-center justify-between relative">
          {/* Dashed bottom border */}
          <div className="nexto-dashed absolute left-10 right-10 bottom-0" />

          <Logo />

          <ul className="hidden md:flex items-center gap-9 list-none">
            {["Our Team", "Solutions", "Showcase", "News"].map((item) => (
              <li key={item}>
                <a
                  href={`#${item.toLowerCase().replace(/\s/g, "-")}`}
                  className="text-[14px] font-normal text-[#1a1a1a] opacity-65 hover:opacity-100 transition-opacity"
                >
                  {item}
                </a>
              </li>
            ))}
          </ul>

          <a
            href="#contact"
            className="nexto-pill-dark hidden md:inline-flex"
            aria-label="Let's Connect"
          >
            <span className="nexto-arrow-circ">
              <ChevronArrow />
            </span>
            Let&apos;s Connect
          </a>

          {/* Hamburger */}
          <button
            className="flex md:hidden flex-col gap-[6px] w-6 h-6 justify-center items-center cursor-pointer z-[61] relative"
            aria-label={menuOpen ? "Close menu" : "Open menu"}
            onClick={() => setMenuOpen((o) => !o)}
          >
            <span
              className={`block w-6 h-[2px] bg-[#111] rounded-sm transition-transform duration-300 ${menuOpen ? "translate-y-2 rotate-45" : ""}`}
            />
            <span
              className={`block w-6 h-[2px] bg-[#111] rounded-sm transition-opacity duration-200 ${menuOpen ? "opacity-0" : ""}`}
            />
            <span
              className={`block w-6 h-[2px] bg-[#111] rounded-sm transition-transform duration-300 ${menuOpen ? "-translate-y-2 -rotate-45" : ""}`}
            />
          </button>
        </div>
      </nav>

      {/* Mobile nav */}
      <div
        className={`fixed inset-0 bg-[#F5F5F5] z-[60] flex flex-col px-8 pt-[90px] pb-10 transition-transform duration-500 ease-[cubic-bezier(0.77,0,0.175,1)] ${menuOpen ? "translate-x-0" : "translate-x-full"}`}
      >
        {["Our Team", "Solutions", "Showcase", "News"].map((item) => (
          <a
            key={item}
            href={`#${item.toLowerCase().replace(/\s/g, "-")}`}
            className="text-[38px] font-black tracking-[-1.5px] text-[#0f0f0f] py-6 border-b border-dashed border-black/15"
            onClick={() => setMenuOpen(false)}
          >
            {item}
          </a>
        ))}
        <a
          href="#contact"
          className="nexto-pill-dark lg mt-6 self-start"
          onClick={() => setMenuOpen(false)}
        >
          <span className="nexto-arrow-circ lg">
            <ChevronArrow />
          </span>
          Let&apos;s Connect
        </a>
      </div>
    </>
  );
}

const stats = [
  { n: "86", sup: "+", label: "Shipped projects across 14 industries." },
  { n: "4.9", sup: "/5", label: "Average client rating since 2019." },
  { n: "23", sup: " days", label: "Median time from brief to first prototype." },
  { n: "100", sup: "%", label: "Of clients return within a year." },
];

export default function Numbers() {
  return (
    <section className="nexto-section pt-0">
      <div className="nexto-wrap">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 rounded-[22px] bg-white overflow-hidden border border-black/5 shadow-[0_2px_14px_rgba(0,0,0,0.04)]">
          {stats.map((s, i) => (
            <div key={i} className="relative p-[30px_26px]">
              {i > 0 && <div className="nexto-dashed-v" />}
              <div className="text-[#0f0f0f] leading-none text-[46px] font-medium tracking-[-2px]">
                {s.n}
                <sup className="text-[22px] font-medium text-[#0f0f0f] align-super ml-[2px] tracking-[-1px]">
                  {s.sup}
                </sup>
              </div>
              <div className="text-[13px] text-[#888] mt-[10px] leading-[1.5] max-w-[200px]">
                {s.label}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

const steps = [
  {
    icon: "chat_bubble",
    title: "Say hi",
