      <div
        ref={trackRef}
        onMouseDown={() => setGrabbing(true)}
        onMouseUp={() => setGrabbing(false)}
        onMouseLeave={() => setGrabbing(false)}
        className={`nexto-scroll-track ${grabbing ? "nexto-scroll-grabbing" : ""}`}
      >
        {/* Left pad to align with content */}
